        unit.position,
        unit.forward,
        unit.currentSpeed,
        unit.definition.speed,
        unit.definition.beam || unit.definition.desiredSize * 0.2,
        unit.definition.sternOffset || unit.definition.desiredSize * 0.48,
        delta
