          googleStatus: this.dom.shell.dataset.googleBattleMapStatus || "disabled",
          googleMapId: this.dom.shell.dataset.googleBattleMapId || "not-set",
          googleRange: Number(this.dom.shell.dataset.googleBattleRange) || 0,
